Sum(
  Sum(
    (
      X[n, c, 
        Max(0, Min(S_h * i + kh - P_h, Dim(X, 2) - 1)), 
        Max(0, Min(S_w * j + kw - P_w, Dim(X, 3) - 1))
      ] * Piecewise(
        (1, (S_h * i + kh - P_h >= 0) & (S_h * i + kh - P_h < Dim(X, 2)) &
            (S_w * j + kw - P_w >= 0) & (S_w * j + kw - P_w < Dim(X, 3))),
        (0, True)
      )
    ),
    (kw, 0, K_w - 1)
  ),
  (kh, 0, K_h - 1)
) / Piecewise(
  (safe_div, safe_div > 0),
  (
    Piecewise(
      (K_h * K_w, count_include_pad & Not(ceil_mode)),
      (
        (Min(S_h * i - P_h + K_h, Dim(X, 2)) - Max(S_h * i - P_h, 0)) * (Min(S_w * j - P_w + K_w, Dim(X, 3)) - Max(S_w * j - P_w, 0)),
        True
      )
    ),
    True
  )
)

Max(
  Piecewise(
    (X[n, c, floor(d * Dim(X, 2) / Dim(Y, 2)) + kd, floor(h * Dim(X, 3) / Dim(Y, 3)) + kh, floor(w * Dim(X, 4) / Dim(Y, 4)) + kw],
     And(
       kd + floor(d * Dim(X, 2) / Dim(Y, 2)) < Dim(X, 2),
       kh + floor(h * Dim(X, 3) / Dim(Y, 3)) < Dim(X, 3),
       kw + floor(w * Dim(X, 4) / Dim(Y, 4)) < Dim(X, 4)
     )
    ),
    (-99999.0, True)
  ),
  (kd, 0, K_d - 1), (kh, 0, K_h - 1), (kw, 0, K_w - 1)
)

Sum(
  Piecewise((X[n, c, ih, iw], Eq(A[n, c, ih, iw], h * Dim(Y, 3) + w)), (0, True)),
  (ih, 0, Dim(X, 2) - 1), (iw, 0, Dim(X, 3) - 1)
) / (
  Sum(
    Piecewise((1, Eq(A[n, c, ih, iw], h * Dim(Y, 3) + w)), (0, True)),
    (ih, 0, Dim(X, 2) - 1), (iw, 0, Dim(X, 3) - 1)
