    Piecewise((1, Eq(A[n, c, id, ih, iw], d * Dim(Y, 3) * Dim(Y, 4) + h * Dim(Y, 4) + w)), (0, True)),
    (id, 0, Dim(X, 2) - 1), (ih, 0, Dim(X, 3) - 1), (iw, 0, Dim(X, 4) - 1)
