                Sum(
                  (Sum(Piecewise((Query[n, l, k_q], batch_first == True), (Query[l, n, k_q], True)) * W_q[h * d_k + i_head, k_q], (k_q, 0, E_q - 1)) + Piecewise((B_q[h * d_k + i_head], bias == True), (0, True))) * Piecewise(
